-- Atlas Forense — baseline idempotente compatível com o schema legado recuperado.
-- Pode ser executado em banco novo; em banco existente use db:preflight antes.
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,openId VARCHAR(64) NOT NULL UNIQUE,name TEXT NULL,email VARCHAR(320) NULL,loginMethod VARCHAR(64) NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updatedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,lastSignedIn TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS legal_topics (id INT AUTO_INCREMENT PRIMARY KEY,parentId INT NULL,kind ENUM('area','subarea','instituto','tema','subtema','questao') NOT NULL,title VARCHAR(255) NOT NULL,slug VARCHAR(191) NOT NULL,pathKey VARCHAR(767) NOT NULL UNIQUE,summary TEXT NULL,synonyms TEXT NULL,cnjCodes TEXT NULL,sourceStatus ENUM('official_confirmed','attachment_reviewed','editorial_review','secondary_pending') NOT NULL DEFAULT 'editorial_review',version INT NOT NULL DEFAULT 1,createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updatedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY legal_topics_parent_slug_unique(parentId,slug),KEY legal_topics_kind_idx(kind)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS evidence_sources (id INT AUTO_INCREMENT PRIMARY KEY,label VARCHAR(255) NOT NULL,sourceType ENUM('official_document','official_url','attachment','secondary','manual') NOT NULL,sourceUrl VARCHAR(1024) NULL,hashSha256 VARCHAR(64) NULL,publicStatus ENUM('official_confirmed','official_without_number','attachment_reviewed','secondary_pending','not_for_use') NOT NULL,note TEXT NULL,lastVerifiedAt TIMESTAMP NULL,createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY evidence_sources_status_idx(publicStatus)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS public_data_sources (id INT AUTO_INCREMENT PRIMARY KEY,sourceKey VARCHAR(191) NOT NULL UNIQUE,label VARCHAR(255) NOT NULL,maintainer VARCHAR(255) NOT NULL,sourceType ENUM('api','catalog','webservice','manual') NOT NULL,baseUrl VARCHAR(1024) NOT NULL,documentationUrl VARCHAR(1024) NOT NULL,authentication ENUM('none','api_key','manual') NOT NULL,integrationStatus ENUM('integrated','ready','credential_required','manual_only','not_integrated') NOT NULL,coverage TEXT NOT NULL,contentScope TEXT NOT NULL,usageNote TEXT NOT NULL,citationText VARCHAR(500) NOT NULL,privacyNote TEXT NOT NULL,lastVerifiedAt TIMESTAMP NULL,createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updatedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY public_data_sources_status_idx(integrationStatus)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS national_census_runs (id INT AUTO_INCREMENT PRIMARY KEY,runKey VARCHAR(191) NOT NULL UNIQUE,sourceKey VARCHAR(191) NOT NULL,status ENUM('planned','running','partial','completed','failed','rejected') NOT NULL,scope VARCHAR(128) NOT NULL,periodStart VARCHAR(7) NOT NULL,periodEnd VARCHAR(7) NOT NULL,expectedTribunals INT NOT NULL,respondedTribunals INT NOT NULL DEFAULT 0,methodologyVersion VARCHAR(64) NOT NULL,queryFingerprint VARCHAR(64) NULL,coverageNote TEXT NOT NULL,createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updatedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY national_census_runs_status_idx(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS national_census_metrics (id INT AUTO_INCREMENT PRIMARY KEY,runId INT NOT NULL,tribunalAlias VARCHAR(64) NOT NULL,tribunal VARCHAR(128) NOT NULL,uf VARCHAR(2) NOT NULL,month VARCHAR(7) NOT NULL,metric ENUM('distribution','baixa') NOT NULL,classCode VARCHAR(32) NOT NULL DEFAULT '',subjectCode VARCHAR(32) NOT NULL DEFAULT '',judgingBodyCode VARCHAR(64) NOT NULL DEFAULT '',amount INT NOT NULL,sourceObservedAt TIMESTAMP NULL,createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY national_census_metric_unique(runId,tribunalAlias,month,metric,classCode,subjectCode,judgingBodyCode),KEY national_census_metrics_month_idx(month),KEY national_census_metrics_tribunal_idx(tribunalAlias)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS national_census_facets (id INT AUTO_INCREMENT PRIMARY KEY,runId INT NOT NULL,kind ENUM('subject','judging_body') NOT NULL,code VARCHAR(64) NOT NULL,label VARCHAR(500) NOT NULL,amount INT NOT NULL,createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY national_census_facets_unique(runId,kind,code),KEY national_census_facets_kind_idx(kind)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS metropolitan_coverage_runs (id INT AUTO_INCREMENT PRIMARY KEY,runKey VARCHAR(191) NOT NULL UNIQUE,sourceKey VARCHAR(191) NOT NULL,tribunalAlias VARCHAR(64) NOT NULL,status ENUM('planned','running','partial','completed','failed','rejected') NOT NULL,scope VARCHAR(128) NOT NULL,periodStart VARCHAR(7) NOT NULL,periodEnd VARCHAR(7) NOT NULL,expectedMunicipalities INT NOT NULL,mappedMunicipalities INT NOT NULL DEFAULT 0,methodologyVersion VARCHAR(64) NOT NULL,queryFingerprint VARCHAR(64) NULL,coverageNote TEXT NOT NULL,createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updatedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY metropolitan_coverage_runs_status_idx(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS metropolitan_judging_body_facets (id INT AUTO_INCREMENT PRIMARY KEY,runId INT NOT NULL,tribunalAlias VARCHAR(64) NOT NULL,municipalityName VARCHAR(128) NOT NULL,municipalityIbgeCode VARCHAR(16) NOT NULL,judgingBodyCode VARCHAR(64) NOT NULL,judgingBodyLabel VARCHAR(500) NOT NULL,amount INT NOT NULL,createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY metropolitan_body_facet_unique(runId,tribunalAlias,municipalityIbgeCode,judgingBodyCode),KEY metropolitan_body_facet_municipality_idx(municipalityIbgeCode),KEY metropolitan_body_facet_alias_idx(tribunalAlias)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS legal_theses (id INT AUTO_INCREMENT PRIMARY KEY,topicId INT NOT NULL,title VARCHAR(500) NOT NULL,position ENUM('favoravel','contraria','condicionada','em_debate') NOT NULL,description TEXT NOT NULL,legalBasis TEXT NULL,proofNotes TEXT NULL,adverseFacts TEXT NULL,sourceStatus ENUM('official_confirmed','attachment_reviewed','editorial_review','secondary_pending') NOT NULL DEFAULT 'editorial_review',lastReviewedAt TIMESTAMP NULL,createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updatedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY legal_theses_topic_idx(topicId),KEY legal_theses_position_idx(position)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ingestion_batches (id INT AUTO_INCREMENT PRIMARY KEY,batchKey VARCHAR(191) NOT NULL UNIQUE,sourceLabel VARCHAR(255) NOT NULL,sourceHash VARCHAR(64) NULL,status ENUM('planned','reviewed','imported','partial','rejected') NOT NULL,itemsDiscovered INT NOT NULL DEFAULT 0,itemsImported INT NOT NULL DEFAULT 0,itemsExcluded INT NOT NULL DEFAULT 0,method TEXT NOT NULL,note TEXT NULL,createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY ingestion_batches_status_idx(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS jurisprudence_records (id INT AUTO_INCREMENT PRIMARY KEY,externalId VARCHAR(191) NOT NULL UNIQUE,batchId INT NOT NULL,sourceId INT NOT NULL,cnjNumber VARCHAR(80) NULL,tribunal VARCHAR(64) NOT NULL,justice VARCHAR(64) NOT NULL,city VARCHAR(128) NULL,comarca VARCHAR(128) NULL,court VARCHAR(255) NULL,judgingBody VARCHAR(255) NULL,decisionType VARCHAR(64) NOT NULL,decisionDate TIMESTAMP NULL,publicationDate TIMESTAMP NULL,legalArea VARCHAR(255) NULL,theme VARCHAR(500) NULL,outcomeOrigin VARCHAR(255) NULL,outcomeAppeal VARCHAR(255) NULL,dispositionType VARCHAR(255) NULL,moralDamageValue VARCHAR(64) NULL,reasoningSummary TEXT NULL,validationNote TEXT NULL,sourceStatus ENUM('official_confirmed','official_without_number','attachment_reviewed','secondary_pending','movement_observed','search_thematic') NOT NULL,recordVersion INT NOT NULL DEFAULT 1,createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updatedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY jurisprudence_tribunal_idx(tribunal),KEY jurisprudence_city_idx(city),KEY jurisprudence_theme_idx(theme),KEY jurisprudence_status_idx(sourceStatus)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS evidence_review_items (id INT AUTO_INCREMENT PRIMARY KEY,jurisprudenceId INT NOT NULL UNIQUE,status ENUM('pending','approved','rejected','returned') NOT NULL DEFAULT 'pending',priority ENUM('routine','elevated','urgent') NOT NULL DEFAULT 'routine',requestedReason TEXT NOT NULL,assignedToUserId INT NULL,decisionNote TEXT NULL,reviewedByUserId INT NULL,reviewedAt TIMESTAMP NULL,createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updatedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY evidence_review_status_idx(status),KEY evidence_review_priority_idx(priority)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS jurisprudence_topics (id INT AUTO_INCREMENT PRIMARY KEY,jurisprudenceId INT NOT NULL,topicId INT NOT NULL,relevance ENUM('primary','secondary') NOT NULL DEFAULT 'primary',UNIQUE KEY jurisprudence_topics_unique(jurisprudenceId,topicId),KEY jurisprudence_topics_topic_idx(topicId)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS thesis_authorities (id INT AUTO_INCREMENT PRIMARY KEY,thesisId INT NOT NULL,jurisprudenceId INT NOT NULL,stance ENUM('supports','opposes','context') NOT NULL,note TEXT NULL,UNIQUE KEY thesis_authorities_unique(thesisId,jurisprudenceId),KEY thesis_authorities_thesis_idx(thesisId)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_events (id INT AUTO_INCREMENT PRIMARY KEY,entityType VARCHAR(64) NOT NULL,entityKey VARCHAR(191) NOT NULL,action VARCHAR(128) NOT NULL,sourceStatus VARCHAR(64) NULL,actorLabel VARCHAR(128) NOT NULL,note TEXT NULL,createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY audit_events_entity_idx(entityType,entityKey)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
